-- =============================================================================
-- 7. AUTOMATION AND APPROVALS
-- =============================================================================
-- PROVEN: rule = name + parent (6 = list) + trigger + conditions + actions JSON; catalog of 22 resource kinds is server data;
--   active/inactive counts per list. ASSUMED: everything about execution (event driven, idempotency, depth limit, usage).
CREATE TABLE automation_resources (                  -- PROVEN catalog (key, display, internal, production, auth_type, dynamic values)
  key text PRIMARY KEY,
  display text NOT NULL,
  internal boolean NOT NULL DEFAULT false,
  production boolean NOT NULL DEFAULT true,
  auth_type text,
  dynamic_values jsonb
);

CREATE TABLE automation_catalog_items (              -- ASSUMED: triggers, conditions, actions as registry rows
  kind text NOT NULL CHECK (kind IN ('trigger','condition','action')),
  key text NOT NULL,
  resource_key text NOT NULL REFERENCES automation_resources(key),
  display text NOT NULL,
  input_schema jsonb NOT NULL DEFAULT '{}',
  enabled boolean NOT NULL DEFAULT true,
  PRIMARY KEY (kind, key)
);

CREATE TABLE automations (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  scope_type text NOT NULL CHECK (scope_type IN ('workspace','space','folder','list')),  -- PROVEN list (6); others ASSUMED
  scope_id uuid NOT NULL,                            -- polymorphic location
  include_descendants boolean NOT NULL DEFAULT false, -- ASSUMED
  name text NOT NULL,
  description text,
  trigger_type text NOT NULL,                        -- extracted from trigger so it can be indexed; e.g. task_created
  trigger jsonb NOT NULL,                            -- PROVEN {type, ...}
  conditions jsonb NOT NULL DEFAULT '[]',            -- PROVEN e.g. [{after:{apis, forms, ...}}]
  actions jsonb NOT NULL,                            -- PROVEN [{type, input}]
  active boolean NOT NULL DEFAULT true,
  created_by uuid /* id -> identity.users */,
  updated_by uuid /* id -> identity.users */,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1                 -- recorded on each run so a run shows which definition ran
);

-- 'rules to evaluate for this event': by workspace + trigger + location.
CREATE INDEX automations_match ON automations (workspace_id, trigger_type, scope_type, scope_id) WHERE active AND deleted_at IS NULL;

-- manager tab per location (PROVEN: count and inactiveCount per list).
CREATE INDEX automations_scope ON automations (workspace_id, scope_type, scope_id) WHERE deleted_at IS NULL;

CREATE TABLE automation_schedules (                  -- ASSUMED: 'Every ...' recurring trigger
  automation_id uuid PRIMARY KEY REFERENCES automations(id) ON DELETE CASCADE,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  rrule text NOT NULL,
  timezone text NOT NULL DEFAULT 'UTC',
  next_run_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE INDEX automation_schedules_due ON automation_schedules (next_run_at);

-- run log: ASSUMED. Idempotency key = '<automation_id>:<event_id>:<target_id>' -> a replayed event cannot run a rule twice.
-- PARTITION BY HASH (workspace_id) x 8 so UNIQUE (workspace_id, idempotency_key) is enforceable.
CREATE TABLE automation_runs (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  id uuid NOT NULL,
  automation_id uuid NOT NULL REFERENCES automations(id),
  automation_version integer NOT NULL,
  event_id uuid,                                     -- change_log.id that triggered it (NULL for schedule/webhook)
  target_type text,
  target_id uuid,
  idempotency_key text NOT NULL,
  depth smallint NOT NULL DEFAULT 0,                 -- = triggering event depth; actions emit events with depth+1; stop at 5
  status text NOT NULL DEFAULT 'running'
         CHECK (status IN ('running','succeeded','failed','skipped','stopped_depth')),
  reason text,                                       -- why failed/skipped
  action_results jsonb NOT NULL DEFAULT '[]',        -- per-action outcome, never filtered
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  PRIMARY KEY (workspace_id, id),
  UNIQUE (workspace_id, idempotency_key)
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('automation_runs', 8);

-- 'run log for automation X' (Activity tab), newest first.
CREATE INDEX automation_runs_rule ON automation_runs (workspace_id, automation_id, started_at DESC);

-- 'what did automations do to this task'.
CREATE INDEX automation_runs_target ON automation_runs (workspace_id, target_type, target_id, started_at DESC);

-- failed runs dashboard / alerting.
CREATE INDEX automation_runs_failed ON automation_runs (workspace_id, started_at DESC) WHERE status IN ('failed','stopped_depth');

CREATE TABLE automation_usage (                      -- ASSUMED counter; PROVEN plan page lists monthly limits (100,000 on Business Plus)
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  month date NOT NULL CHECK (month = date_trunc('month', month)::date),
  runs integer NOT NULL DEFAULT 0,
  run_limit integer,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, month)
);

-- ordered chain: lower step first
ALTER TABLE automations ADD COLUMN consecutive_failures smallint NOT NULL DEFAULT 0;

ALTER TABLE automations ADD COLUMN disabled_reason text;
